Lemma zwin_get : forall s off len (i : int),
  zwin s off len = true ->
  (to_Z len <= to_Z PrimString.max_length)%Z ->
  (to_Z off <= to_Z i < to_Z off + to_Z len)%Z ->
  PrimString.get s i = c0 /\ (to_Z off + to_Z len <= to_Z (PrimString.length s))%Z.
