(* [comment removed for export] *)
Lemma scanN_prefix_zwin : forall s (p n : N) (off len : int),
  scanN s 64 0 p = true ->
  zwin s off len = true ->
  to_Z off = Z.of_N (2 * p) -> to_Z len = Z.of_N (2 * (n - p)) -> (p <= n)%N ->
  (to_Z len <= to_Z PrimString.max_length)%Z ->
  scanN s 64 0 n = true.
